//! Earshot desktop app (T7.1, T7.2, T7.3): the Tauri 2 shell. The UI (`packages/ui`, React) talks
//! to Rust only through the typed commands and events in [`ipc`]; their TypeScript bindings
//! are generated by tauri-specta into `packages/ui/src/ipc/bindings.ts` and drift-checked by
//! a test. A live meeting runs on its own thread ([`meeting`]); the tray, the global shortcut
//! and the notifications are [`shell`].

// No console window in release builds.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod activity;
mod audio_check;
mod audio_settings;
mod benchmark;
mod check_child;
mod crash;
mod credentials;
#[cfg(windows)]
mod credentials_win;
mod cuda_files;
mod cuda_settings;
mod detail;
mod first_run;
#[cfg(windows)]
mod folder_picker_win;
mod folders;
mod general;
mod headless;
mod ipc;
mod jobs;
mod keep_local;
mod llama_probe;
mod meeting;
mod meeting_events;
mod model_jobs;
mod models;
mod obsidian;
#[cfg(test)]
mod page_names_tests;
mod plain_text;
mod shell;
mod speaker_settings;
mod storage_settings;
mod summaries;
mod summary_style;
mod summary_vocabulary;
#[cfg(test)]
mod testutil;
#[cfg(windows)]
mod toast_win;
mod transcription_probe;
mod update_settings;
#[cfg(windows)]
mod wer_win;

use std::sync::Arc;
use std::time::Instant;

use tauri::Manager;
use tauri_specta::Event;

fn main() {
    // The hidden model check mode runs and exits before anything of the app (Tauri, the
    // store, the window) is built.
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(1).collect();
    // Crash logs (T9.1e) go to the app's data folder, also from the check; the replay mode keeps
    // them in its own `--data` once that is checked.
    if !headless::asked(&args) {
        crash::install_default();
        // Before any model or child process, and in the child modes too (T9.1t). The replay mode
        // leaves the user's registry alone.
        #[cfg(windows)]
        wer_win::opt_out();
    }
    if let Some(code) = check_child::child_main(&args) {
        std::process::exit(code);
    }
    // So does the trial of a set of llama.cpp's DLLs, which may end its process.
    if let Some(code) = llama_probe::child_main(&args) {
        std::process::exit(code);
    }
    // And the trial of the CUDA transcription folder, for the same reason.
    if let Some(code) = transcription_probe::child_main(&args) {
        std::process::exit(code);
    }
    // And a summary on the graphics card, so a driver crash costs only that summary (T9.3).
    if let Some(code) = earshot_runtime::summary_child::child_main(&args) {
        std::process::exit(code);
    }
    earshot_runtime::summary_child::use_this_exe();
    // And an NPU compile (T12.12b): the app itself never closes the session that compiled.
    if let Some(code) = earshot_runtime::npu_compiled::child_main(&args) {
        std::process::exit(code);
    }
    earshot_runtime::npu_compiled::use_this_exe();
    // So does the replay mode of `accept m7`: no window or webview exists in it.
    if let Some(code) = headless::main_if_asked(&args) {
        std::process::exit(code);
    }
    // Only the app itself: a child may be running while an earlier crash's dump is being written.
    crash::remove_old_dumps();
    let by_windows = shell::started_by_windows(&args);
    let builder = ipc::specta_builder();
    let gate = activity::WorkGate::for_app();
    tauri::Builder::default()
        // First, as its docs ask: a second start of Earshot opens this one's window instead of
        // a second recorder and tray icon.
        .plugin(tauri_plugin_single_instance::init(|app, _, _| {
            if let Some(shell) = app.try_state::<Arc<shell::Shell>>() {
                shell.show_window();
            }
        }))
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .invoke_handler(builder.invoke_handler())
        .on_window_event(|window, event| {
            if let Some(shell) = window.try_state::<Arc<shell::Shell>>() {
                shell.on_window_event(window, event);
            }
        })
        .setup(move |app| {
            builder.mount_events(app);
            // Opening the store runs migrations once; a failure is kept and reported by the
            // commands that need the store, so the window still opens.
            let state = ipc::AppState::open_default();
            // A crash while replacing the speech helpers: back before anything reads them.
            if let Ok(services) = state.services() {
                let models = earshot_runtime::host::model_dir(&services.data);
                earshot_runtime::host::recover_extractions(&models);
            }
            // The CUDA switch (T8.4af) before anything can call llama.cpp or load ONNX Runtime,
            // whose libraries cannot be replaced once loaded. It closes their gates and returns at
            // once; its work runs on a thread, so the window and the tray do not wait. Off, it costs
            // one store read.
            let cuda_files: Arc<dyn earshot_runtime::cuda_switch::CudaFiles> =
                cuda_files::ManifestCudaFiles::new(Arc::new(earshot_runtime::SystemClock));
            let handle = app.handle().clone();
            let cuda_start = state.services().map_or_else(
                |_| cuda_settings::CudaLatch::resolved_off(),
                |services| {
                    cuda_settings::begin(&services, Arc::clone(&cuda_files), move || {
                        let _ = cuda_settings::CudaEvent::StartChecked.emit(&handle);
                    })
                },
            );
            let cuda_latch = Arc::clone(&cuda_start);
            app.manage(cuda_start);
            // The NPU model a meeting would load, compiled in the helper now (T12.12b), so the
            // first meeting usually loads it in a second. Nothing loads in this process.
            #[cfg(target_arch = "aarch64")]
            if let Ok(services) = state.services() {
                let models = earshot_runtime::host::model_dir(&services.data);
                let _ = std::thread::Builder::new()
                    .name("earshot-npu-prepare".into())
                    .spawn(move || {
                        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                            earshot_runtime::host::prepare_npu_model(&services, &models)
                        }));
                    });
            }
            // Audio retention runs now and periodically (T7.4k).
            let retention = storage_settings::RetentionStatus::default();
            if let Ok(services) = state.services() {
                storage_settings::spawn_retention(
                    services,
                    retention.clone(),
                    storage_settings::RETENTION_PERIOD,
                );
            }
            // In-app updates (T9.1b): what an earlier update left goes first; a check only if the
            // user turned automatic checks on.
            let handle = app.handle().clone();
            let update_sink: update_settings::UpdateSink =
                Arc::new(move |e: update_settings::UpdateEvent| {
                    let _ = e.emit(&handle);
                });
            let update_dir = state.data_dir().map(earshot_runtime::update::updates_dir);
            if let Some(dir) = &update_dir {
                earshot_runtime::update::remove_leftovers(dir);
            }
            let update_jobs = update_settings::UpdateJobs::new(
                Arc::new(update_settings::HostUpdates::new(
                    update_dir,
                    Arc::new(earshot_runtime::SystemClock),
                )),
                update_sink,
            );
            let check_now = state.services().is_ok_and(|services| {
                earshot_runtime::update::auto_check(&services.store()).unwrap_or(false)
            });
            if check_now {
                let _ = update_jobs.start_check(true);
            }
            app.manage(update_jobs);
            app.manage(state);
            app.manage(retention);
            let handle = app.handle().clone();
            let sink: meeting::Sink = Arc::new(move |e: meeting_events::MeetingEvent| {
                // Only to this app's own webview; nothing leaves the device.
                let _ = e.emit(&handle);
                if let Some(shell) = handle.try_state::<Arc<shell::Shell>>() {
                    shell.on_meeting_event(&e);
                }
            });
            app.manage(meeting::MeetingDriver::new(
                Arc::new(meeting::HostPrepare::wasapi()),
                sink,
                Arc::new(Instant::now),
                gate.clone(),
            ));
            let handle = app.handle().clone();
            let job_sink: jobs::JobSink = Arc::new(move |e: jobs::JobEvent| {
                let _ = e.emit(&handle);
                if let Some(shell) = handle.try_state::<Arc<shell::Shell>>() {
                    shell.on_job_event(&e);
                }
            });
            app.manage(jobs::JobRunner::new(
                Arc::new(jobs::HostJobs),
                job_sink,
                gate.clone(),
            ));
            let handle = app.handle().clone();
            let model_sink: model_jobs::ModelSink =
                Arc::new(move |e: model_jobs::ModelJobEvent| {
                    let _ = e.emit(&handle);
                });
            let model_jobs = model_jobs::ModelJobs::new(
                Arc::new(model_jobs::HostModelWork),
                model_sink,
                gate.clone(),
            );
            app.manage(model_jobs.clone());
            let handle = app.handle().clone();
            let cuda_sink: cuda_settings::CudaSink =
                Arc::new(move |e: cuda_settings::CudaEvent| {
                    let _ = e.emit(&handle);
                });
            // A run that chose CUDA for transcription finds the stored check out of date.
            if let Ok(services) = app.state::<ipc::AppState>().services() {
                cuda_settings::check_after_start(
                    cuda_latch,
                    services,
                    model_jobs.clone(),
                    Arc::clone(&cuda_sink),
                );
            }
            app.manage(cuda_settings::CudaJobs::new(
                cuda_files, cuda_sink, model_jobs,
            ));
            app.manage(gate.clone());
            let handle = app.handle().clone();
            let voice_sink: speaker_settings::VoiceSink =
                Arc::new(move |e: speaker_settings::VoiceEvent| {
                    let _ = e.emit(&handle);
                });
            app.manage(speaker_settings::VoiceJobs::new(
                Arc::new(speaker_settings::HostVoiceWork),
                voice_sink,
                gate.clone(),
            ));
            let handle = app.handle().clone();
            let check_sink: audio_check::AudioCheckSink =
                Arc::new(move |e: audio_check::AudioCheckEvent| {
                    let _ = e.emit(&handle);
                });
            app.manage(audio_check::AudioCheckJobs::new(
                Arc::new(audio_check::HostAudioCheckWork),
                check_sink,
                gate.clone(),
            ));
            let handle = app.handle().clone();
            let bench_sink: benchmark::BenchmarkSink =
                Arc::new(move |e: benchmark::BenchmarkEvent| {
                    let _ = e.emit(&handle);
                });
            app.manage(benchmark::BenchmarkJobs::new(
                Arc::new(benchmark::HostBenchmarkWork),
                bench_sink,
                gate.clone(),
            ));
            let min_size = app
                .config()
                .app
                .windows
                .iter()
                .find(|w| w.label == "main")
                .and_then(|w| Some((w.min_width?, w.min_height?)));
            app.manage(ipc::CompactWindow::new(min_size));
            app.manage(shell::ShortcutStatus::default());
            let shell = Arc::new(shell::Shell::new(app.handle().clone()));
            app.manage(Arc::clone(&shell));
            let tray = shell.build_tray();
            shell.register_shortcut();
            // The window starts hidden: started by Windows it stays so (T7.5), unless there is
            // no tray to open it from.
            if !by_windows || tray.is_err() {
                shell.show_window();
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("the Earshot window could not start");
}
